// Fellow on the business's own Developer API key: every operation in Fellow's API reference (developers.fellow.ai) —
// notes and their agendas, recordings with transcripts and AI notes, API uploads, action items and webhooks.
// actions.json is generated by `bun scripts/openapi-actions.ts fellow`. AI notes and action items start automations by
// webhook (triggers.ts); new notes, recordings and action items by polling (polls/fellow.ts).
import { AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

// Every workspace has its own host (<subdomain>.fellow.app), so the key is pasted with it: <subdomain>:<key>.
// The workspace's address works too: https://northwind.fellow.app:<key>
export function split(secret: string) {
  const m = /^\s*(?:https?:\/\/)?([a-z0-9][a-z0-9-]*)(?:\.fellow\.(?:app|ai))?\/?:(.+)$/i.exec(secret);
  if (!m) throw new AppsError("paste your Fellow workspace and API key joined by a colon, like northwind:YOUR_API_KEY (northwind as in northwind.fellow.app)");
  return { subdomain: m[1]!.toLowerCase(), token: m[2]!.trim() };
}

export const api: Api = {
  name: "Fellow",
  base: "https://{subdomain}.fellow.app",
  tokenHelp: "Fellow → User settings → Developer API",
  auth: (secret) => ({ "X-API-KEY": split(secret).token }),
  url: (secret, _base, path) => `https://${split(secret).subdomain}.fellow.app${path}`,
};

export const fellow: OwnApp = {
  app: "fellow",
  name: "Fellow",
  logo: "/logos/fellow.png",
  keyField: {
    label: "Workspace and API key",
    help: "In Fellow, open User settings → Developer API, click Generate API key, name it Emplio and copy it (it's shown once). No Developer API section? A workspace admin turns it on in Workspace settings → Security. Paste your workspace name, a colon and the key, all on one line: for northwind.fellow.app that's northwind:YOUR_API_KEY. Emplio sees what you see in Fellow; a Super Admin key (Enterprise) sees the whole workspace and can delete notes and recordings.",
    placeholder: "northwind:your-api-key",
  },
  async check(secret) {
    split(secret);
    const me = (await call(api, secret, { method: "GET", path: "/api/v1/me", query: [], headers: [] }, {})) as { user?: { full_name?: string; email?: string }; workspace?: { name?: string } };
    const who = me.user?.full_name || me.user?.email || "Fellow";
    return me.workspace?.name ? `${who} (${me.workspace.name})` : who;
  },
  push: {
    events,
    triggers,
    start: (secret, connection, event) => watch(api, secret, connection, event),
    stop: (secret, id) => unwatch(api, secret, id),
    receive: (delivery) => receive(delivery),
    wanted,
  },
  actions: await specActions(new URL("./actions.json", import.meta.url), api),
};
